using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
public static class V4Tests {
 static void Check(bool value,string name){if(!value)throw new Exception(name);}
 public static int SettingsUi(string directory){Directory.CreateDirectory(directory);var options=new Settings();options.Servers.Add(Storage.DefaultServer());var editor=new SettingsWindow(options.Copy(),true);editor.Loaded+=(a,b)=>editor.Dispatcher.BeginInvoke((Action)(()=>{var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;((ComboBox)typeof(SettingsWindow).GetField("themePicker",flags).GetValue(editor)).SelectedIndex=3;((ComboBox)typeof(SettingsWindow).GetField("frequency",flags).GetValue(editor)).SelectedItem="2";((ComboBox)typeof(SettingsWindow).GetField("retention",flags).GetValue(editor)).SelectedItem="7";((ComboBox)typeof(SettingsWindow).GetField("archiveCap",flags).GetValue(editor)).SelectedItem="256";var footer=(Grid)editor.Root.Children[editor.Root.Children.Count-1];((Button)footer.Children[3]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));bool? result=editor.ShowDialog();Check(result==true&&editor.Result.ThemeName=="light"&&editor.Result.Interval==2&&editor.Result.RetentionDays==7&&editor.Result.ArchiveLimitMB==256,"actual settings save flow");Check(options.ThemeName=="graphite"&&options.Interval==5,"original settings untouched");File.WriteAllText(Path.Combine(directory,"settings-ui-results.txt"),"ACTUAL_THEME_FREQUENCY_RETENTION_CAPACITY_SELECTION_AND_SAVE=True\nORIGINAL_SETTINGS_UNTOUCHED=True\nREGISTRY_UNCHANGED=True\n");return 0;}
 public static int Live(string directory){Directory.CreateDirectory(directory);var window=new MonitorWindow(true);var log=new List<string>();for(int i=0;i<6;i++){var m=Remote.Collect(Storage.DefaultServer());Check(string.IsNullOrEmpty(m.Error),m.Error);Check(m.CpuCores.Count>100,"live multicore collection");Check(m.Gpus.Count==8,"live 8 GPUs");Check(!double.IsNaN(ResourceSample.ParsePercent(m.Cpu)),"live total CPU");window.SetMetrics(m);log.Add(DateTime.Now.ToString("HH:mm:ss")+" CPU="+m.Cpu+" AVAILABLE="+m.Cores+" SYSTEM_LOGICAL="+m.CpuCores.Count+" GPU="+m.Gpus.Count+" SAMPLES="+window.History.Count);if(i<5)System.Threading.Thread.Sleep(2000);}
 window.SwitchView("CPU");window.RenderImage(Path.Combine(directory,"cpu-live.png"),1100,800,120);window.ShowCores();window.RenderImage(Path.Combine(directory,"cpu-cores-live.png"),1100,800,120);window.SwitchView("GPU");window.RenderImage(Path.Combine(directory,"gpu-live.png"),1100,800,120);window.Scroll.ScrollToBottom();window.RenderImage(Path.Combine(directory,"gpu-processes-live.png"),1100,800,120);window.SwitchView("内存");window.RenderImage(Path.Combine(directory,"memory-live.png"),1100,800,120);window.ApplyAppearance("light");window.SwitchView("CPU");window.RenderImage(Path.Combine(directory,"light-live.png"),1100,800,120);log.Add("LIVE_HISTORY_SAMPLES="+window.History.Count);window.Exit();File.WriteAllLines(Path.Combine(directory,"live-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}
 public static int Run(string directory){Directory.CreateDirectory(directory);var checks=new List<string>();Storage.PathName=Path.Combine(directory,"options.xml");
 var window=new MonitorWindow(true);var m=Program.Fixture("eight");window.SetMetrics(m);int n=window.History.Count;
 window.SwitchView("GPU");window.SwitchView("内存");window.SwitchView("CPU");Check(window.History.Count==n,"switch should not create samples");checks.Add("TAB_SWITCH_DOES_NOT_FABRICATE_SAMPLES=True");
 var first=((Server)window.ServerPicker.SelectedItem).Copy();var second=new Server{Name="CPU only",Host="192.0.2.44",User="test",Port=22};window.ChooseServer(second);Check(window.History.Count==0,"new server history");window.SetMetrics(Program.Fixture("none"));Check(window.History.Count==1&&window.CardViews.Count==0,"no GPU CPU server");window.ChooseServer(first);Check(window.History.Count==n,"server isolation");window.SetMetrics(new Metrics{Error="offline"});Check(window.History.Count==n,"errors are not measurements");checks.Add("SERVER_HISTORY_ISOLATED=True");checks.Add("FAILED_POLLS_NOT_RECORDED=True");checks.Add("CPU_ONLY_SERVER_SUPPORTED=True");
 Check(m.CpuCores.Count==128,"128 logical CPUs");Check(ResourceSample.MemoryPercent("50 / 100 MiB")==50,"memory calculation");Check(double.IsNaN(ResourceSample.MemoryPercent("—")),"missing memory not zero");checks.Add("MULTICORE_128=True");
 int renders=0;foreach(string theme in Theme.Keys){foreach(int seconds in new[]{2,7,30,120}){var options=new Settings{ThemeName=theme,Interval=seconds};options.Servers.Add(first.Copy());var cancelled=options.Copy();cancelled.ThemeName="cancelled";cancelled.Servers[0].Host="192.0.2.9";Check(options.Servers[0].Host==first.Host&&options.ThemeName==theme,"settings isolation");Storage.Save(options);var loaded=Storage.Load();Check(loaded.ThemeName==theme&&loaded.Interval==seconds,"persistence");window.ApplyOptions(loaded);Check(window.PollSeconds==seconds,"timer applies saved interval");}
 window.SetMetrics(m);foreach(string view in new[]{"CPU","GPU","内存"})foreach(int[] size in new[]{new[]{760,560},new[]{1100,800}})foreach(int dpi in new[]{96,120,192}){window.SwitchView(view);window.RenderImage(Path.Combine(directory,theme+"-"+view+"-"+size[0]+"-"+dpi+".png"),size[0],size[1],dpi);Check(window.Audit().Count==0,"layout "+theme+view+size[0]+dpi);Check(window.CpuValue.ActualHeight>=16&&window.MemoryValue.ActualHeight>=16&&window.DiskValue.ActualHeight>=16,"footer text measured");renders++;}}
 checks.Add("THEME_INTERVAL_PERSISTENCE=True");checks.Add("LIVE_TIMER_INTERVAL_APPLIED=True");checks.Add("SETTINGS_CANCEL_ISOLATION=True");checks.Add("THEME_TAB_SIZE_DPI_RENDERS="+renders);
 window.ApplyOptions(new Settings{Servers=new List<Server>{first},ThemeName="forest",Interval=5});window.SetMetrics(m);window.History.Clear();var now=DateTime.UtcNow;for(int i=0;i<=60;i++)window.History.Add(new ResourceSample{Time=now.AddSeconds(-300+i*5),Cpu=25+20*Math.Sin(i*.3)+i*.35,Memory=35+i*.12});window.SwitchView("CPU");window.RenderImage(Path.Combine(directory,"cpu-demo-synthetic.png"),1100,800,120);window.SwitchView("内存");window.RenderImage(Path.Combine(directory,"memory-demo-synthetic.png"),1100,800,120);checks.Add("DEMO_PREVIEWS_SYNTHETIC=True");window.Exit();File.WriteAllLines(Path.Combine(directory,"v4-results.txt"),checks);Console.WriteLine(string.Join("\n",checks));return 0;
 }
}
